function validateForm(e){e=document.getElementById(e);if(!e)return console.error("Formulário não encontrado!"),!1;e=e.querySelectorAll("input[required], textarea[required]");let t=!0;return e.forEach(e=>{""===e.value.trim()?(e.classList.add("error"),t=!1):e.classList.remove("error")}),t}function loadImages(){document.querySelectorAll("img[data-src]").forEach(e=>{e.src=e.getAttribute("data-src")})}document.addEventListener("DOMContentLoaded",function(){console.log("Página carregada com sucesso!"),document.querySelectorAll(".product-button").forEach(e=>{e.addEventListener("click",function(e){e.preventDefault(),alert("Produto adicionado ao carrinho!")}),e.addEventListener("mouseover",function(){this.style.transform="scale(1.05)"}),e.addEventListener("mouseout",function(){this.style.transform="scale(1)"})}),document.querySelectorAll(".menu a").forEach(e=>{e.addEventListener("click",function(e){e.preventDefault();e=this.getAttribute("href"),e=document.querySelector(e);e&&e.scrollIntoView({behavior:"smooth"})})}),console.log("Scripts inicializados com sucesso!")});